package com.jotalbot.madworld.data
import org.json.JSONObject
import java.util.UUID

/** Pure JSON -> state parsers for authoritative responses. Kept free of I/O so golden-file tests can exercise them. */
object MadWorldJson {
 internal fun parseEconomyOverview(json:String):EconomyOverviewState{val r=JSONObject(json);val jobs=buildList{val a=r.getJSONArray("active_jobs");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(EconomyJobState(UUID.fromString(x.getString("id")),x.getString("kind"),UUID.fromString(x.getString("recipe_id")),UUID.fromString(x.getString("settlement_id")),x.getString("state"),x.getString("completes_at")))}};val f=buildList{val a=r.getJSONArray("facilities");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(EconomyFacilityState(x.getString("code"),x.getInt("level"),x.getInt("efficiency_bps")))}};return EconomyOverviewState(UUID.fromString(r.getString("settlement_id")),r.getString("region"),r.getInt("warehouse_capacity"),r.getInt("warehouse_used"),f,jobs,r.getInt("contract_count"),r.getInt("ready_vehicles"),r.getInt("market_price_points"),r.getString("next_action"))}
 internal fun parseState(json:String):PlayerState{val r=JSONObject(json);val ch=if(r.isNull("character"))null else parseCharacter(r.getJSONObject("character"));val v=buildList{val a=r.getJSONArray("vehicles");for(i in 0 until a.length())add(parseVehicle(a.getJSONObject(i)))};val w=if(r.isNull("wallet"))null else r.getJSONObject("wallet").let{WalletState(UUID.fromString(it.getString("id")),it.getLong("balance"),it.getInt("version"))};val inv=buildList{val a=r.getJSONArray("inventory");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(InventoryState(UUID.fromString(x.getString("inventory_id")),UUID.fromString(x.getString("item_definition_id")),x.getLong("quantity"),x.getInt("condition"),x.getInt("version")))}};val jobs=buildList{val a=r.getJSONArray("active_jobs");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(JobState(UUID.fromString(x.getString("id")),UUID.fromString(x.getString("owner_id")),x.getString("job_type"),x.getString("started_at"),x.getString("completes_at"),x.getString("state"),x.getInt("version")))}};return PlayerState(ch,v,w,inv,jobs)}
 internal fun parseCharacter(j:JSONObject)=CharacterState(UUID.fromString(j.getString("id")),UUID.fromString(j.getString("player_id")),j.getString("name"),j.getInt("level"),j.getInt("version"))
 internal fun parseVehicle(j:JSONObject)=VehicleState(UUID.fromString(j.getString("id")),UUID.fromString(j.getString("owner_id")),j.getString("code"),j.getString("chassis_code"),j.getInt("durability"),j.getInt("fuel"),j.getString("state"),j.getInt("version"))
 internal fun parseSettlement(json:String,playerId:UUID):SettlementState{val r=JSONObject(json);if(UUID.fromString(r.getString("owner_id"))!=playerId)throw ApiException("settlement owner mismatch");val m=r.getJSONObject("modules");val cap=r.getJSONObject("capabilities");return SettlementState(UUID.fromString(r.getString("id")),playerId,r.getString("region"),r.getInt("level"),buildMap{m.keys().forEach{put(it,m.getInt(it))}},buildMap{cap.keys().forEach{put(it,cap.getBoolean(it))}},r.getInt("version"))}
 internal fun parseTerritory(json:String):TerritoryState{val r=JSONObject(json);val regions=buildList{val a=r.getJSONArray("regions");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(TerritoryRegionState(x.getString("id"),x.getString("name"),x.getString("security"),x.getLong("version")))}};val control=buildList{val a=r.getJSONArray("control");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(TerritoryControlState(x.getString("region_id"),x.getString("target_type"),x.getString("target_id"),if(x.isNull("controller_corporation_id"))null else UUID.fromString(x.getString("controller_corporation_id")),if(x.isNull("controlled_since"))null else x.getString("controlled_since"),x.getLong("version")))}};val roads=buildList{val a=r.getJSONArray("roads");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(TerritoryRoadState(UUID.fromString(x.getString("id")),x.getString("region_id"),x.getString("from_node"),x.getString("to_node"),if(x.isNull("controller_corporation_id"))null else UUID.fromString(x.getString("controller_corporation_id")),x.getInt("travel_modifier_bps"),x.getInt("risk_modifier_bps"),x.getLong("version")))}};val resources=buildList{val a=r.getJSONArray("resource_sites");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(TerritoryResourceSiteState(UUID.fromString(x.getString("id")),x.getString("region_id"),x.getString("resource_type"),x.getString("name"),if(x.isNull("controller_corporation_id"))null else UUID.fromString(x.getString("controller_corporation_id")),x.getLong("capacity"),x.getLong("remaining"),x.getLong("renewal_rate"),x.getLong("extraction_limit"),x.getLong("version")))}};return TerritoryState(regions,control,roads,resources,r.getBoolean("authoritative"))}
 internal fun parseWorld(json:String):WorldState{
        val r=JSONObject(json)
            val s=r.getJSONObject("simulation")
            val factions=buildList{val a=r.getJSONArray("factions");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldFactionState(x.getString("id"),x.getString("name"),x.getString("doctrine"),x.getInt("aggression_bps"),x.getInt("logistics_bps")))}}
            val pressures=buildList{val a=r.getJSONArray("pressures");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldPressureState(x.getString("region_id"),x.getString("resource_type"),x.getInt("pressure_bps"),x.getInt("trend_bps"),x.getLong("available_quantity"),x.getLong("target_quantity")))}}
            val events=buildList{val a=r.getJSONArray("events");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldEventState(x.getString("id"),x.getLong("tick"),if(x.isNull("region_id"))null else x.getString("region_id"),if(x.isNull("faction_id"))null else x.getString("faction_id"),x.getString("event_type"),x.getInt("severity"),x.getString("state")))}}
            val missions=buildList{val a=r.getJSONArray("missions");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldMissionState(x.getString("id"),x.getString("region_id"),x.getString("mission_type"),x.getString("title"),x.getLong("reward_credits"),x.getInt("risk_bps"),x.getString("state")))}}
            val discoveries=buildList{val a=r.getJSONArray("discoveries");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldDiscoveryState(x.getString("id"),x.getString("region_id"),x.getString("resource_type"),x.getLong("quantity"),x.getString("state")))}}
            val disasters=buildList{val a=r.getJSONArray("disasters");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(WorldDisasterState(x.getString("id"),x.getString("region_id"),x.getString("disaster_type"),x.getInt("severity"),x.getInt("hazard_bps"),x.getInt("travel_risk_bps"),x.getInt("extraction_modifier_bps")))}}
            return WorldState(s.getInt("season"),s.getLong("tick"),r.getBoolean("authoritative"),factions,pressures,events,missions,discoveries,disasters)
 }
}
